ref_dict.teo:areageneral:
\begin{theorem}\label{teo:areageneral}
Let $\mu$ be a regular measure and a Borel measure over a homogeneous group $\G$, 
and let $a>0$. We fix a Borel set $A \subset \G$ and
assume that the following conditions hold:
\begin{enumerate}
    \item $A$ has a countable covering whose elements are open and have $\mu$-finite measure,
    \item the subset $\{x \in A : \theta^a(\mu,x) = 0\}$ is $\sigma$-finite with respect to $\mathcal{S}^a$,
    \item $\mu \mres A$ is absolutely continuous with respect to $\mathcal{S}^a \mres A$.
\end{enumerate}
Then $\theta^a(\mu, \cdot) : A \to [0,+\infty]$ is Borel and for every Borel set $B \subset A$ we have
\begin{equation*}
        \mu(B) = \int_B \theta^a(\mu, p) d \mathcal{S}^a(p).
    \end{equation*}
\end{theorem}

ref_dict.teotrascu:
\begin{theorem}\label{teotrascu}
	Let $\Sigma\subset\E$ be a $2$-dimensional $C^{1,\alpha}$ smooth submanifold with $2\le d(\Sigma)\le 4$ and let $C(\Sigma)\subset \Sigma$ be the subset of points of degree less than $d(\Sigma)$. Then we have
	\begin{equation}\label{eq:SN0}
		\mathcal{S}^{d(\Sigma)}(C(\Sigma)) = 0
	\end{equation}
	whenever $(d(\Sigma)-2)/d(\Sigma)<\alpha\le 1$. 
\end{theorem}

ref_dict.horizontalnon:
\begin{theorem}\label{horizontalnon}
There does not exist any $C^1$ smooth surface of degree $2$ in the Engel group.
\end{theorem}

