ref_dict.thm:HZ-k-equivalence:
\begin{theorem}\label{thm:HZ-k-equivalence}
    If $X$ and $X'$ are $K$-equivalent smooth projective varieties over $\CC$ then $H^i(X,\ZZ)\simeq H^i(X',\ZZ)$ for all $i$.
\end{theorem}

ref_dict.checks:
\begin{proposition}\label{checks}
    Let $X$ and $Y$ be smooth projective complex algebraic varieties. Then
    \begin{enumerate}
        \item If $Z\subset X$ is a smooth projective subvariety of codimension $c$, $\pi:\text{Bl}_Z(X)\to X$ is the blow-up of $X$ along $Z$, and $E$ is the exceptional divisor of the blowup, then $$H_{\ZZ}(X)-H_{\ZZ}(Z) = H_{\ZZ}(\text{Bl}_Z(X)) - H_{\ZZ}(E).$$
        \item $H_{\ZZ}(X\times Y) = H_{\ZZ}(X)H_{\ZZ}(Y)$ 
    \end{enumerate}
    In particular, $H_{\ZZ}$ extends to a function
    \[
    H_{\text{vir},\ZZ}\colon K_0(\text{Var}_\CC)\to R.
    \]
\end{proposition}

ref_dict.lemma isogeny:
\begin{lemma}\cite[Lemma 5.1]{BHS}
\label{lemma isogeny}
Let $k$ be a field.  Let $\~G \to G$ be a central isogeny of semisimple algebraic groups, the kernel of which is a group $\mu$ of multiplicative type.  If $\pi_0^{\A^1}(\~G)$ is strongly $\A^1$-invariant, then so is $\pi_0^{\A^1}(G)$.
\end{lemma}

ref_dict.thm intro main:
\begin{theorem}\cite[Theorem 1.1, Remark 1.2]{BHS}
\label{thm intro main}
If $G$ is an algebraic group over a perfect field $k$, then $\pi_0^{\#A^1}(G)$ is a strongly $\#A^1$-invariant sheaf. Consequently, for any Nisnevich locally
trivial $G$-torsor $\@P \to \@X$ in $\@H(k)$,
\[
P \to X \to BG
\]
is an $\#A^1$-fiber sequence.
\end{theorem}

sketch:
One of the key steps in the proof of Theorem \ref{thm intro main} is \cite[Lemma 5.1]{BHS}. The note’s strategy is to “give a complete and self-contained proof of \cite[Lemma 5.1]{BHS}, thereby completing the proof of Theorem \ref{thm intro main},” because the proof in \cite{BHS} is said to be incomplete (it “relies on a result in \cite{Choudhury-Hogadi}, the proof of which contains a gap,” and “the existence of the key exact sequence … is not properly justified”). The outlined proof plan is:
\begin{itemize}
\item Section \ref{section preliminaries}: preliminaries on “long exact sequences of simplicial homotopy groups associated with homotopy principal fibrations of simplicial sheaves.”
\item Section \ref{section key LES}: establish “the key exact sequence mentioned in (2) above.”
\item Section \ref{section main result}: use the results of Section \ref{section key LES} together with “an argument circumventing the use of results from \cite{Choudhury-Hogadi}” to prove \cite[Lemma 5.1]{BHS} (see Lemma \ref{lemma isogeny}), which in turn completes the proof of Theorem \ref{thm intro main}.
\end{itemize}

