  \begin{equation*}
    \lambda_1(\mathcal{P}_{N_0}) > \lambda_1(\mathcal{P}_{N_0+1}) >
    \dots > \lambda_1(\mathcal{P}_N) > \lambda_1(\mathcal{P}_{N+1}) >
