ref_dict.thm:main:
\begin{thm}\label{thm:main}
Let $N,k \geq 2$ with $(N,k) \notin \{(8,10), (10,8)\}$ and let $A\in \mathcal{C}(\mathfrak{sl}_N, k)$ be a $1$-super-transitive \`etale algebra object. Then either:
\begin{enumerate}[(i)]
    \item $k = N-2$ and $A$ is a simple current extension of $A_{\mathfrak{sl}_{N(N-1)/2}}$, or 
    \item $k = N$ and $A$ is a simple current extension of $A_{\mathfrak{so}_{N^2-1}}$, or 
    \item $k = N+2$ and $A$ is a simple current extension of $A_{\mathfrak{sl}_{N(N+1)/2}}$.
    \end{enumerate}
\end{thm}

ref_dict.thm:classN-2:
\begin{thm}\label{thm:classN-2}
    Let $A\in \mathcal{C}$ be 1-super-transitive, and let $k= N-2$. Then there exists a faithful dominant monoidal functor
    \[   \overline{ \mathcal{SD}^-_N } \to \mathcal{C}_A                 \]
    In particular, $A$ is a simple current extension of $A_{\mathfrak{sl}_{N(N-1)/2}}$.
\end{thm}

ref_dict.thm:classN+2:
\begin{thm}\label{thm:classN+2}
    Let $A\in \mathcal{C}$ be 1-super-transitive, and let $k= N+2$. Then there exists a faithful dominant monoidal functor
    \[   \overline{ \mathcal{SD}^+_N } \to \mathcal{C}_A                 \]
    In particular, $A$ is a simple current extension of $A_{\mathfrak{sl}_{N(N+1)/2}}$.
\end{thm}

