For any $(x,t)\in D\times(0,T]$, the law of the random variable $u(x,t)$ is absolutely continuous with respect to the Lebesgue measure on $\mR$.
\end{theorem}

ref_dict.main lemma 2:
\begin{lemma} \label{main lemma 2}
Let $n\in\mN_{*}$ be fixed and consider the unique solution $u_{n}$ of equation $(\ref{mild formulation of u_n})$. Then: \\[0.05cm]
$1)$ For any $(x,t)\in D\times[0,T]$, it holds $u_{n}(x,t)\in\mD^{1,2}$ with the Malliavin derivative of $u_{n}(x,t)$ satisfying\\[0.05cm] \phantom{1)} almost surely and uniquely the stochastic partial differential equation
\begin{equation} \label{mal. der. of u_n}
D_{y,s}u_{n}(x,t) = \int_{s}^{t} \int_{D} G_{zz}(x,z,t-\tau) \cg_{n}(z,\tau) D_{y,s}u_{n}(z,\tau)\, dzd\tau + \sigma \big{[} K^{*}_{H} \big{(} G(x,\diamond,t-\bullet) \textup{\textbf{1}}_{[0,t]}(\bullet) \big{)} \big{]} (y,s)
\end{equation}
\phantom{1)} for all $(y,s)\in D\times[0,t]$ while $D_{y,s}u_{n}(x,t)=0$ if $(y,s)\in D\times(t,T]$. Here $\cg_{n}(x,t)$ is a stochastic process\\ \phantom{1)} such that
\begin{equation*}
\left | \cg_{n}(x,t) \right | \leq c(n)\ \text{a.s.},\ \forall (x,t)\in D\times[0,T].
\end{equation*}
$2)$ It holds $\{u_{n}\}_{n\in\mN_{*}}\subset\mL^{1,2}$.
\end{lemma}

ref_dict.important remark:
\begin{remark} \label{important remark} 
$1)$ It is straightforward that   $\mD^{1,2}\subseteq\mD^{1,2}_{\textup{\text{loc}}}$ and $\mL^{1,2}\subseteq\mL^{1,2}_{\textup{\text{loc}}}$. Moreover, it holds $\mD^{1,2}\subseteq\mD^{1,1}$ $($cf. \cite{N}, p. $27)$ thus $\mD^{1,2}_{\textup{\text{loc}}}\subseteq\mD^{1,1}_{\textup{\text{loc}}}$.\\[0.1cm]
$2)$ If $F\in\mD^{1,2}_{\textup{loc}}$ and $\{(\Omega_{n},F_{n})\}_{n \in \mN_{*}}$ localizes $F$ in $\mD^{1,2}$, then $DF$ is defined without ambiguity by $DF=DF_{n}$ on $\Omega_{n},\ n\geq1$.
\end{remark}

ref_dict.important estimate:
\begin{lemma} \label{important estimate}
For any $\hat{s} \in (0,T]$ and any $\epsilon \in (0,\hat{s}]$, there exists a constant $\cc=\cc(\sigma,H,n,T)>0$ such that
\begin{equation} \label{R.R.6} 
\sup_{t\in[\hat{s}-\epsilon,\hat{s}]} \sup_{x \in D} E \bigg{(} \int_{\hat{s}-\epsilon}^{\hat{s}}\int_{D} | D_{y,s}u_{n}(x,t) |^2\, dyds \bigg{)} \leq \cc\, \epsilon^{\frac{4H-1}{2}} \exp \left ( \frac{4}{3}\, \epsilon^{\frac{3}{4}} \right ).
\end{equation}
\end{lemma}

