\section{Impossibility to drop the innate regularity assumption}\label{s:counterex}

The following example shows that we cannot drop the innate regularity assumption in \cref{f:GT}: 

\begin{example}[without innate regularity, G\"unt\"urk-Thao fails]
\label{ex:counterex}
Suppose that $X=\ell_2(\mathbb{N})$ with orthonormal basis $(e_n)_{n\in\mathbb{N}}$. Suppose that $(\theta_n)_{n\in\mathbb{N}}$ is a decreasing sequence of angles in $]0,\pi/2[$ with $\theta_n\to0$. Consider the collection $\mathcal{L} = \{L_1,L_2\}$ 
of two closed linear subspaces where $L_1:=\cspan\{\cos(\theta_k)e_{2k-1}+\sin(\theta_k)e_{2k}\mid k\in\mathbb{N}\smallsetminus\{0\}\}$ and $L_2:=\cspan\{e_{2k+1}\mid k\in\mathbb{N}\}$. We have
\begin{enumerate}[ref=\currentenv~\theexample(\roman*)]
    \item\label{ex:counterexi} $P_{L_1}x=\sum_{k\in\mathbb{N}\smallsetminus\{0\}}\left(x_{2k-1}\cos(\theta_k)+x_{2k}\sin(\theta_k)\right)\left(e_{2k-1}\cos(\theta_k)+e_{2k}\sin(\theta_k)\right)$.
    \item\label{ex:counterexii} $P_{L_2}x=(0,x_1,0,x_3,0,x_5,\dots)$.
    \item\label{ex:counterexiii} $\mathcal{L}$ is not innately regular.
\end{enumerate}
