\begin{theorem}\label{thm12}
For all integers $n\geq 0$ and $k\geq 1$, we have 
\begin{align}\label{eq14}
A_5(2^{k+1}n+3\cdot 2^k-2) =  B_kA_5(4n+4)+\left(\dfrac{8^{k+1}-1}{7}-9B_k\right)A_5(2n+1),
\end{align}
