ref_dict.prop:stacky_recollement:
\begin{proposition}
    \label{prop:stacky_recollement}
    Let $\mathcal{X}$ be a quasi-compact quasi-separated algebraic stack. Suppose $j\colon \mathcal{U}\to \mathcal{X}$ is a quasi-compact open immersion. Set $Z:=|\mathcal{X}|\setminus |\mathcal{U}|$. There exists a recollement
    \begin{displaymath}
        \begin{tikzcd}
            {D_{\operatorname{qc}}(\mathcal{U})} && {D_{\operatorname{qc}}(\mathcal{X})} && {D_{\operatorname{qc},Z}(\mathcal{X})}
            \arrow["{\mathbf{R}j_\ast}"{description}, from=1-1, to=1-3]
            \arrow["{\mathbf{L}j^\ast}"', shift right=3, bend right = 12pt, from=1-3, to=1-1]
            \arrow["{j^!}", shift left=3, bend right = -12pt, from=1-3, to=1-1]
            \arrow["{i^!}"{description}, from=1-3, to=1-5]
            \arrow["{i_\ast}"', shift right=3, bend right = 12pt, from=1-5, to=1-3]
            \arrow["{i^\ast}", shift left=3, bend right = -12pt, from=1-5, to=1-3]
        \end{tikzcd}
    \end{displaymath}
    where in particular $i_\ast$ is the natural inclusion and $j^!$ the right adjoint of $\mathbf{R}j_\ast$.
\end{proposition}

