ref_dict.approximate:
\begin{theorem}
\label{approximate}
 Given a number field $K$ with ring of integers $\mathcal{O}_K$, let $f\in \mathcal{O}_K[x]$ be a polynomial. Let $X$ be a smooth closed subvariety of $\mathbb{A}^n_{\mathcal{O}_K}$ with $\mathrm{codim}(X)=d$, which is geometrically irreducible over K. For a nonzero integral ideal $\mathfrak{n}$ of $\mathcal{O}_K$ such that $X$ has a good reduction at $\mathfrak{p}$ for any prime ideal $\mathfrak{p}\vert \mathfrak{n}$, we have
    $$\#\mathscr{E}_{f,\mathfrak{n}}(X)=(\mathrm{N}_{K/\mathbb{Q}}(\mathfrak{n}))^{n-d}\exp\left({O\left(\frac{\log\mathrm{N}_{K/\mathbb{Q}}(\mathfrak{n})}{\log\log\mathrm{N}_{K/\mathbb{Q}}(\mathfrak{n})}\right)}\right).$$
    The implied constant in the $O$-terms depends only on $K,X$ and $f$.
\end{theorem}

ref_dict.main:
\begin{theorem}
\label{main}
    Given a number field $K$ with ring of integers $\mathcal{O}_K$, let $f\in \mathcal{O}_K[x]$ be a polynomial, and $X$ be a smooth closed subscheme of $\mathbb{A}^n_{\mathcal{O}_K}$ with $\mathrm{codim}(X)=d$. For a nonzero integral ideal $\mathfrak{n}$ of $\mathcal{O}_K$ such that $X$ has a good reduction at $\mathfrak{p}$ for every prime ideal $\mathfrak{p}\vert \mathfrak{n}$, we have
 $$\#\mathscr{E}_{f,\mathfrak{n}}(X)=(\mathrm{N}_{K/\mathbb{Q}}(\mathfrak{n}))^{n-d}\prod_{\mathfrak{p}\vert \mathfrak{n}}\left(\frac{\#X(\mathcal{O}_K/\mathfrak{p})-\# \mathcal{N}^f(\mathfrak{p},X)}{(\mathrm{N}_{K/\mathbb{Q}}(\mathfrak{p}))^{n-d}}\right),$$
 where $\mathcal{N}^f(\mathfrak{p},X)=\{(x_1,\dots,x_n)\in X(\mathcal{O}_K/\mathfrak{p}):\prod_{i=1}^{n}\Bar{f}(x_i)=0\}$, $\mathrm{N}_{K/\mathbb{Q}}$ denotes the norm map in $K/\mathbb{Q}$, $\Bar{f}$ is the image of $f$ under the projection  $\mathcal{O}_K\longrightarrow \mathcal{O}_K/\mathfrak{p}$.
\end{theorem}

